# name: half_balance_choice_rate
# description: Among trials where the two sequences differ in local imbalance (the summed |#H - #T| over the first and second halves, minus the whole-sequence |#H - #T|), the proportion choosing the sequence with GREATER local imbalance; observed below the null means people demand balance within each half (representativeness of sub-sequences) more than the model's global imbalance term predicts, above means less.
def test_statistic(df):
    def loc(s):
        h = len(s) // 2
        f, g = s[:h], s[h:]
        return (abs(f.count("H") - f.count("T")) + abs(g.count("H") - g.count("T"))
                - abs(s.count("H") - s.count("T")))
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: loc(s) for s in u}
    la = df["sequence_a"].map(m).to_numpy()
    lb = df["sequence_b"].map(m).to_numpy()
    sel = la != lb
    if sel.sum() == 0:
        return 0.5
    c = df["chose_left"].to_numpy()
    chose = np.where(la > lb, c, 1 - c)
    return float(chose[sel].mean())

# name: balance_at_equal_alternation
# description: Among trials where both sequences have the same number of alternations but different |#H - #T|, the proportion choosing the MORE balanced sequence; observed above the null means people weight heads/tails balance more than the model's imbalance term predicts once switching is held fixed, below means less.
def test_statistic(df):
    def alt(s):
        return sum(1 for x, y in zip(s, s[1:]) if x != y)
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    ma = {s: alt(s) for s in u}
    mi = {s: abs(s.count("H") - s.count("T")) for s in u}
    aa = df["sequence_a"].map(ma).to_numpy()
    ab = df["sequence_b"].map(ma).to_numpy()
    ia = df["sequence_a"].map(mi).to_numpy()
    ib = df["sequence_b"].map(mi).to_numpy()
    sel = (aa == ab) & (ia != ib)
    if sel.sum() == 0:
        return 0.5
    c = df["chose_left"].to_numpy()
    chose = np.where(ia < ib, c, 1 - c)
    return float(chose[sel].mean())

# name: triplet_diversity_choice_rate
# description: Among trials (length >= 5) where the two sequences contain different numbers of distinct length-3 substrings (e.g. HHT, THT), the proportion choosing the sequence with MORE distinct triplets; observed above the null means people reward local pattern variety beyond what the alternation/balance/streak/symmetry terms predict, below means less.
def test_statistic(df):
    def ntrip(s):
        return len({s[i:i + 3] for i in range(len(s) - 2)})
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: ntrip(s) for s in u}
    ta = df["sequence_a"].map(m).to_numpy(dtype=float)
    tb = df["sequence_b"].map(m).to_numpy(dtype=float)
    L = df["sequence_a"].str.len().to_numpy()
    sel = (ta != tb) & (L >= 5)
    if sel.sum() == 0:
        return 0.5
    c = df["chose_left"].to_numpy()
    chose = np.where(ta > tb, c, 1 - c)
    return float(chose[sel].mean())

# name: longer_initial_run_choice_rate
# description: Among trials whose sequences open with runs of different length (as a share of the length), the proportion choosing the sequence with the LONGER opening run; observed above the null means people tolerate (or favour) an opening streak more than the model predicts, below means they penalise it more (the model weighs only the final and longest runs).
def test_statistic(df):
    def first_run(s):
        k = 1
        while k < len(s) and s[k] == s[0]:
            k += 1
        return k / len(s)
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: first_run(s) for s in u}
    fa = df["sequence_a"].map(m).to_numpy(dtype=float)
    fb = df["sequence_b"].map(m).to_numpy(dtype=float)
    sel = fa != fb
    if sel.sum() == 0:
        return 0.5
    c = df["chose_left"].to_numpy()
    chose = np.where(fa > fb, c, 1 - c)
    return float(chose[sel].mean())

# name: longer_streak_at_equal_alternation
# description: Among trials where both sequences have the same number of alternations but different longest-run lengths, the proportion choosing the sequence with the LONGER longest run; observed below the null means people penalise a concentrated streak (vs. spread-out repeats) more than the model's longest-run weight predicts, above means less.
def test_statistic(df):
    def stats(s):
        alt = sum(1 for x, y in zip(s, s[1:]) if x != y)
        best = cur = 1
        for x, y in zip(s, s[1:]):
            cur = cur + 1 if x == y else 1
            best = max(best, cur)
        return alt, best
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    ma = {s: stats(s)[0] for s in u}
    mr = {s: stats(s)[1] for s in u}
    aa = df["sequence_a"].map(ma).to_numpy()
    ab = df["sequence_b"].map(ma).to_numpy()
    ra = df["sequence_a"].map(mr).to_numpy()
    rb = df["sequence_b"].map(mr).to_numpy()
    sel = (aa == ab) & (ra != rb)
    if sel.sum() == 0:
        return 0.5
    c = df["chose_left"].to_numpy()
    chose = np.where(ra > rb, c, 1 - c)
    return float(chose[sel].mean())

# name: short_sequence_higher_alternation_rate
# description: Among trials with sequences of length <= 7 whose alternation rates differ, the proportion choosing the sequence with the HIGHER alternation rate; observed above the null means people's preference for switching is stronger on short sequences than the model's length-independent ideal-rate term predicts, below means weaker.
def test_statistic(df):
    def alt(s):
        return sum(1 for x, y in zip(s, s[1:]) if x != y) / (len(s) - 1)
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: alt(s) for s in u}
    aa = df["sequence_a"].map(m).to_numpy(dtype=float)
    ab = df["sequence_b"].map(m).to_numpy(dtype=float)
    L = df["sequence_a"].str.len().to_numpy()
    sel = (L <= 7) & (aa != ab)
    if sel.sum() == 0:
        return 0.5
    c = df["chose_left"].to_numpy()
    chose = np.where(aa > ab, c, 1 - c)
    return float(chose[sel].mean())
